import React, { useEffect, useMemo, useState } from 'react';
import Col from 'react-bootstrap/Col';
import Row from 'react-bootstrap/Row';
import FormGroup from '@mui/material/FormGroup';
import TextField from '@mui/material/TextField';
import FormControl from '@mui/material/FormControl';
import Autocomplete from '@mui/material/Autocomplete';
import FormControlLabel from '@mui/material/FormControlLabel';
import PropTypes from 'prop-types';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  IconButton,
  styled,
  Select,
  MenuItem,
} from '@mui/material';
import CloseIconText from '@mui/icons-material/Close';
import Checkbox from '@mui/material/Checkbox';
import { Button } from 'react-bootstrap';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import { Link } from 'react-router-dom';
import Pagination from '@mui/material/Pagination';
import Stack from '@mui/material/Stack';
import CloseIcon from '../../Assets/Img/close.svg';
import { useDispatch, useSelector } from 'react-redux';
import {
  // getDashboardComparisonData,
  getstoreErrorListData,
  setIsStoreErrorUpdated,
  updateStoreError,
} from 'store/reducers/Dashboard/Dashboard.slice';
import Loader from 'Components/Common/Loader';
import moment from 'moment';
import { getAllPageData2, getPageListData2 } from 'utils/gropingPagination';
import { getTotalPages } from 'utils/common';
import useGroupSortable from 'utils/useGroupSortable';
import { Form, Formik } from 'formik';
import { getEventListData } from 'store/reducers/Admin/Events/Parties/parties.slice';
import { getUserListData } from 'store/reducers/User/user.slice';
import {
  getWatchListData,
  resetWatchlist,
} from 'store/reducers/Admin/Events/WatchList/watchlist.slice';
import WatchList from './WatchList';
import { getFollowupNote } from 'store/reducers/Admin/System/noteTypes.slice';
import FollowupNote from './FollowupNote';

const BootstrapDialog = styled(Dialog)(({ theme }) => ({
  '& .MuiDialogContent-root': {
    padding: theme.spacing(2),
  },
  '& .MuiDialogActions-root': {
    padding: theme.spacing(1),
  },
}));

function BootstrapDialogTitle(props) {
  const { children, onClose, ...other } = props;

  return (
    <DialogTitle sx={{ m: 0, p: 2 }} {...other}>
      {children}
      {onClose ? (
        <IconButton
          aria-label="close"
          onClick={onClose}
          sx={{
            position: 'absolute',
            right: 19,
            top: 19,
            color: theme => theme.palette.grey[600],
          }}
        >
          <CloseIconText />
        </IconButton>
      ) : null}
    </DialogTitle>
  );
}

BootstrapDialogTitle.propTypes = {
  children: PropTypes.node,
  onClose: PropTypes.func.isRequired,
};

let pageSize = 10;

const initialValuesAccount = {
  minPlaces: 0,
  maxPlaces: 10000,
  upperLimit: 50,
  lowerLimit: 0,
  theVenue: '',
  owner_id: '',
  hideBookings: false,
  hideEnquiries: false,
  hideConfirmed: false,
  hideProvisional: false,
  hideExclusive: false,
  hideMixed: false,
  theLcMin: 0,
  theLcMax: -1001,
  showSQL: false,
};
export default function HomePage() {
  const dispatch = useDispatch();
  // const [isAutomationToggle, setAutomationToggle] = useState(true);

  // const handleCloseAutomationToggle = () => {
  //   setAutomationToggle(false);
  // };

  const [accountsInitialValues, setAccountInitialValues] =
    useState(initialValuesAccount);
  const { activeEventList, inActiveEventList, eventLoading, eventDateDetail } =
    useSelector(({ parties }) => parties);
  const { watchList, watchListLoading } = useSelector(
    ({ watchlist }) => watchlist,
  );

  const { activeUserList } = useSelector(({ user }) => user);

  const { storeErrorLoading, storeErrorData, isStoreUpdateError } = useSelector(
    ({ storeError }) => storeError,
  );
  const [open, setOpen] = useState(false);
  const [noteData, setNoteData] = useState('');

  const [places, setPlaces] = useState({
    active: {},
  });

  const [activeAllPageData, setActiveAllPageData] = useState([]);

  const [currentPage, setCurrentPage] = useState({
    activeCurrentPage: 1,
  });

  const activeIndexOfLastItem = currentPage.activeCurrentPage * pageSize;
  const activeIndexOfFirstItem = activeIndexOfLastItem - pageSize;

  const totalActiveRecordPage = useMemo(() => {
    const totalActiveRecordCount = getTotalPages(storeErrorData, pageSize);
    return totalActiveRecordCount;
  }, [storeErrorData]);

  useEffect(() => {
    return () => {
      dispatch(resetWatchlist());
    };
  }, []);

  const setCurrentPageHandler = key => {
    setCurrentPage({
      ...currentPage,
      [key]: currentPage[key] - 1,
    });
  };

  useEffect(() => {
    if (storeErrorData?.length > 0) {
      let currentDataList = [];
      currentDataList = getAllPageData2(
        storeErrorData,
        currentPage.activeCurrentPage,
        pageSize,
        totalActiveRecordPage,
        setCurrentPageHandler,
        'activeCurrentPage',
      );
      setActiveAllPageData(currentDataList);
    }
  }, [storeErrorData, totalActiveRecordPage]);

  const activeCurrentData = useMemo(() => {
    let currentDataList = [];
    if (activeAllPageData?.length > 0) {
      currentDataList = getPageListData2(
        storeErrorData,
        activeAllPageData,
        currentPage.activeCurrentPage,
        totalActiveRecordPage,
        setCurrentPageHandler,
        'activeCurrentPage',
      );
    }
    return currentDataList;
  }, [activeAllPageData, storeErrorData, currentPage]);

  const handleInputChange = (e, index, name) => {
    const { value } = e.target;
    setPlaces(prevPlaces => {
      return {
        ...prevPlaces,
        [name]: {
          ...prevPlaces[name],
          [index]: {
            ...prevPlaces[name][index],
            place: value,
            errorMessage: '',
          },
        },
      };
    });
  };

  useEffect(() => {
    // dispatch(getDashboardComparisonData());
    dispatch(getstoreErrorListData());
    dispatch(getEventListData());
    dispatch(getUserListData());
    dispatch(getFollowupNote());
  }, []);

  useEffect(() => {
    if (isStoreUpdateError) {
      dispatch(getstoreErrorListData());
      dispatch(setIsStoreErrorUpdated(false));
    }
  }, [isStoreUpdateError]);

  const handleClickOpen = item => {
    setNoteData(item?.tech);
    setOpen(true);
  };
  const handleClose = () => {
    setOpen(false);
  };

  const { itemsActive, requestSortActive } = useGroupSortable(
    currentPage.activeCurrentPage,
    activeCurrentData,
  );

  return (
    <div className="inner_wrapper">
      {(storeErrorLoading || watchListLoading) && <Loader />}
      <div className="page_title">
        <h1>Dashboard</h1>
      </div>
      <WatchList />
      <div className="system_error_wrap">
        <div className="p-2">
          <h5>System Errors</h5>
          <p>Great! There are currently no unresolved errors logged</p>
        </div>
        {itemsActive?.length > 0 ? (
          <div className="table_main_Wrapper vertical_top">
            <TableContainer component={Paper}>
              <Table sx={{ minWidth: 650 }} aria-label="simple table">
                <TableHead>
                  <TableRow>
                    <TableCell>
                      <span onClick={() => requestSortActive('error_date')}>
                        Error Time
                      </span>
                    </TableCell>
                    <TableCell>
                      <span onClick={() => requestSortActive('function')}>
                        Error
                      </span>
                    </TableCell>
                    <TableCell>
                      <span onClick={() => requestSortActive('details')}>
                        Details
                      </span>
                    </TableCell>
                    <TableCell>Technical Info</TableCell>
                    <TableCell>Resolution Notes</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {itemsActive?.length > 0 &&
                    itemsActive?.map((item, itemIndex) => {
                      return (
                        <TableRow key={itemIndex}>
                          <TableCell>
                            {moment(item?.error_date).format('L h:mm:ss')}
                          </TableCell>
                          <TableCell>{item?.function}</TableCell>
                          <TableCell>
                            <span className="w_200">{item?.details}</span>
                          </TableCell>
                          <TableCell>
                            <Link onClick={() => handleClickOpen(item)}>
                              Show/Hide Info
                            </Link>
                          </TableCell>
                          <TableCell>
                            <div className="resolution_note_wrap">
                              <Row className="g-0">
                                <Col>
                                  <TextField
                                    id="resolution_note"
                                    multiline
                                    value={
                                      places?.active[
                                        activeIndexOfFirstItem + 1 + itemIndex
                                      ]?.place || ''
                                    }
                                    onChange={e =>
                                      handleInputChange(
                                        e,
                                        activeIndexOfFirstItem + 1 + itemIndex,
                                        'active',
                                      )
                                    }
                                    rows={3}
                                    variant="outlined"
                                  />
                                  <div className="d-block">
                                    <Button
                                      className="btn_border small mt-2"
                                      onClick={() => {
                                        dispatch(
                                          updateStoreError({
                                            resolved_note: {
                                              note: places['active'][
                                                activeIndexOfFirstItem +
                                                  1 +
                                                  itemIndex
                                              ]?.place,
                                            },
                                            _id: item?._id,
                                          }),
                                        );
                                      }}
                                    >
                                      Mark as Resolved
                                    </Button>
                                  </div>
                                </Col>
                                <Col className="ps-3">
                                  Resolution Notes:{' '}
                                  <span>{item?.resolved_note}</span>
                                </Col>
                              </Row>
                            </div>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                </TableBody>
              </Table>
            </TableContainer>
            <div className="table_pagination_wrap">
              {itemsActive?.length > 0 ? (
                <Row className="g-0 align-items-center my-2">
                  <Col sm={6}>
                    <div className="total_entry">
                      {/* <p className="m-0">
                            Showing {activeIndexOfFirstItem + 1} to{' '}
                            {Math.min(
                              activeIndexOfLastItem,
                              storeErrorData?.length,
                            )}{' '}
                            of {storeErrorData?.length} entries
                          </p> */}
                      <p className="m-0">
                        Showing {activeIndexOfFirstItem + 1} to{' '}
                        {Math.min(
                          activeIndexOfLastItem,
                          storeErrorData?.length,
                        )}{' '}
                        of {storeErrorData?.length} entries
                      </p>
                    </div>
                  </Col>
                  <Col sm={6}>
                    <div className="pagination_wrap">
                      <Stack spacing={2}>
                        <Pagination
                          count={totalActiveRecordPage}
                          page={currentPage.activeCurrentPage}
                          onChange={(e, page) => {
                            setCurrentPage({
                              ...currentPage,
                              activeCurrentPage: page,
                            });
                          }}
                        />
                      </Stack>
                    </div>
                  </Col>
                </Row>
              ) : (
                ''
              )}
            </div>
          </div>
        ) : (
          ''
        )}
      </div>
      <FollowupNote />
      {/* <div className="automation_job_error">
        <div className="p-2">
          <h5>Automation / Cron Job Errors</h5>
          <p>No cron job errors logged</p>
        </div>
        <div className="number_comparision bg_white_box p-3">
          <h5>Numbers Comparison</h5>
          <p>
            NOTE: The graph below is comparing all venues from last year to all
            venues this year - that means it is comparing 19 venues in 2021 to
            17 venues in 2022. Show Previous Years
          </p>
          {isAutomationToggle && (
            <div className="note_danger">
              Cannot read properties of undefined (reading 'd'){' '}
              <img
                onClick={handleCloseAutomationToggle}
                src={CloseIcon}
                alt="close icon"
              />
            </div>
          )}
        </div>
      </div> */}
      <BootstrapDialog
        aria-labelledby="customized-dialog2-title"
        open={open}
        className="small_popup system_error_note_popup"
      >
        <BootstrapDialogTitle
          id="customized-dialog2-title"
          onClose={handleClose}
        ></BootstrapDialogTitle>
        <DialogContent dividers>
          <div className="popup_content_wrap">
            <code>{noteData}</code>
          </div>
        </DialogContent>
      </BootstrapDialog>
    </div>
  );
}
